package zkcircuit

import (
	"errors"
	"strings"
	"testing"
)

// TestScratchPrivateNoLeak exercises every channel by which private input
// bytes could reach an error message.
func TestScratchPrivateNoLeak(t *testing.T) {
	// distinct secret tokens that must never appear in any diagnostic
	cases := []struct {
		name  string
		doc   string
		want  string // substring the diagnostic MUST contain
	}{
		{"illegal char", `{"public":[],"private":["123QWE"]}`, "private input #1"},
		{"empty", `{"public":[],"private":[""]}`, "private input #1"},
		{"minus only", `{"public":[],"private":["-"]}`, "private input #1"},
		{"plus", `{"public":[],"private":["+7"]}`, "private input #1"},
		{"number element", `{"public":[],"private":[123456]}`, "private input #1"},
		{"object element", `{"public":[],"private":[{"SECRETKEY":1}]}`, "private input #1"},
		{"dup key object", `{"public":[],"private":[{"SECRETKEY":1,"SECRETKEY":2}]}`, "private input #1"},
		{"bool", `{"public":[],"private":[true]}`, "private input #1"},
		{"null", `{"public":[],"private":[null]}`, "private input #1"},
		{"nested array", `{"public":[],"private":[["SECRETVAL"]]}`, "private input #1"},
		{"syntax in private", `{"public":[],"private":["SECRET"  ]}`, "private"},
		{"garbage in private", `{"public":[],"private":SECRETVAL}`, "private"},
		{"second index", `{"public":[],"private":["1","-BADVAL"]}`, "private input #2"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := parseWitness([]byte(tc.doc), 0, 1)
			if !errors.Is(err, ErrInvalidInput) {
				t.Fatalf("want input format error, got %v", err)
			}
			msg := err.Error()
			t.Logf("diagnostic: %s", msg)
			for _, secret := range []string{"SECRET", "QWE", "123456", "BADVAL", "SECRETVAL"} {
				if strings.Contains(msg, secret) {
					t.Fatalf("diagnostic leaked %q: %s", secret, msg)
				}
			}
			if !strings.Contains(msg, tc.want) {
				t.Fatalf("diagnostic missing %q: %s", tc.want, msg)
			}
		})
	}

	// Corruption that cannot be reliably attributed to a group: generic.
	for _, doc := range []string{`{SECRETSYNTAX`, `{"public" SECRET`, `{"public":[1],"private":[1] GARBAGE`} {
		_, err := parseWitness([]byte(doc), 0, 1)
		msg := err.Error()
		t.Logf("generic: %s", msg)
		if !errors.Is(err, ErrInvalidInput) {
			t.Fatalf("want input format error for %q, got %v", doc, err)
		}
		if strings.Contains(msg, "SECRET") || strings.Contains(msg, "GARBAGE") {
			t.Fatalf("generic diagnostic leaked document text: %s", msg)
		}
	}

	// Structural messages name the group and required format.
	structCases := []struct {
		doc     string
		pub     int
		priv    int
		wantSub string
	}{
		{`{"private":[]}`, 0, 0, "public"},
		{`{"public":[]}`, 0, 0, "private"},
		{`{"public":["1"],"private":[]}`, 2, 0, "public input length mismatch"},
		{`{"public":[],"private":["1"]}`, 0, 2, "private input length mismatch"},
		{`{"public":null,"private":[]}`, 0, 0, "public"},
		{`{"public":1,"private":[]}`, 0, 0, "public"},
	}
	for _, tc := range structCases {
		_, err := parseWitness([]byte(tc.doc), tc.pub, tc.priv)
		msg := err.Error()
		t.Logf("struct: %s", msg)
		if !errors.Is(err, ErrInvalidInput) {
			t.Fatalf("want input format error for %q, got %v", tc.doc, err)
		}
		if !strings.Contains(msg, tc.wantSub) {
			t.Fatalf("for %q want substring %q in: %s", tc.doc, tc.wantSub, msg)
		}
	}

	// Public diagnostics retain detail (value and character may be quoted).
	_, err := parseWitness([]byte(`{"public":["9Q"],"private":[]}`), 1, 0)
	t.Logf("public detail: %v", err)
	if err == nil || !strings.Contains(err.Error(), "public input #1") {
		t.Fatalf("public diagnostic should keep detail and position: %v", err)
	}
}

